import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"50、【鼎】 巽下離上","description":"周易口訣義 - 50、【鼎】 巽下離上","frontmatter":{"title":"50、【鼎】 巽下離上","description":"周易口訣義 - 50、【鼎】 巽下離上"},"headers":[],"relativePath":"classics/koujueyi/052.md","filePath":"classics/koujueyi/052.md"}'),r={name:"classics/koujueyi/052.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_50、【鼎】-巽下離上" tabindex="-1">50、【鼎】 巽下離上 <a class="header-anchor" href="#_50、【鼎】-巽下離上" aria-label="Permalink to “50、【鼎】 巽下離上”">​</a></h1><p>彖曰：鼎，象也。以木巽火，亨飪也。聖人亨以享上帝，而大亨以養聖賢。巽而耳目聰明，柔進而上行，得中而應乎剛，是以「元亨」。</p><p>象曰：木上有火，「鼎」，君子以正位凝命。</p><p>初六：鼎顛趾，利出否。得妾以其子，無咎。</p><p>象曰：「鼎顛趾」，未悖也；「利出否」，以從貴也。</p><p>九二：鼎有實，我仇有疾，不我能即，吉。</p><p>象曰：「鼎有實」，慎所之也；「我仇有疾」，終無尤也。</p><p>九三：鼎耳革，其行塞，雉膏不食，方雨虧悔，終吉。</p><p>象曰：「鼎耳革」，失其義也。</p><p>九四：鼎折足，覆公餗，其形渥，兇。</p><p>象曰：「覆公餗」，信如何也！</p><p>六五：鼎黃耳金鉉，利貞。</p><p>象曰：「鼎黃耳」，中以為實也。</p><p>上九：鼎玉鉉，大吉，無不利。</p><p>象曰：玉鉉在上，剛柔節也。</p><p>解讀</p><p>「鼎元吉亨」者，鼎者器象之名，故何妥雲：「古者鑄金為此器，能調五味，變故取新，以成烹飪之用，以供宗廟，次養聖賢。」天子以天下為鼎，諸侯以國為鼎，變故成新，尤須當理，故先元吉，後乃亨通，故曰「元吉亨」也。象曰「木上有火，鼎」者，「巽」木也，又為入，「離」，火也。木入火中，是烹飪，鼎之象也。「君子以正位凝命」者，凝，嚴整也。鼎既變故成新，所以君子象之，正定尊卑之位，使其有別；布示嚴凝之命，使其不妄輕犯也。</p><p>初六，「鼎顛趾，利出否，得妾以其子，無咎」者，趾，足也；顛，倒也。「鼎」之為義，下實上虛，虛以納物，實以受物也。今初六以陰處下，即是鼎口向下，鼎足倒上，即是鼎傾覆，足倒在上，故曰「鼎顛趾」也。鼎既「顛趾」，其所利者，利在傾棄鄙穢之物，故曰「利出否也」。以事明之，亦猶正室雖亡，媵妾不可為室主。若以妾為室主，亦猶鼎之顛趾，咎莫大焉。妾若有子，即母以子貴，以此繼室，猶可免咎，故曰「得妾以其子，無咎」也。</p><p>「九二，鼎有實，我仇有疾，不我能即，吉」者，實為陽也，即，就也。鼎之為義，虛中待物，乃是其常。今九二以陽居中，失虛中之義，施之人事，即是志意盈滿，不受規誨，故曰「鼎有實」也。「我仇」謂五也；仇，匹也。然六五是我之仇匹，有乘剛之疾，不得來就於我，為六五下有二剛爻，為疾也。我得全其志，不為驕盈，即獲吉也，故曰「我仇有疾，不我能即，吉」也。</p><p>「九三，鼎耳革，其行塞，雉膏不食，方雨虧悔，終吉」者，鼎之為義，下實上虛。九三既處下卦之上，即是鼎耳。「鼎耳」之用，唯在虛空，以待鉉而舉之。今九三以陽處之，而自實塞，即是變革鼎耳之常道也，故曰「鼎耳革」。以人事明之，是懷小人之行而自實塞，不納賢良，故曰「其行塞」也。既無虛中待物之心，物亦不來歸己，猶之雉膏美物而終不得食，故曰「雉膏不食」也。「方雨虧悔，終吉」者，此戒其勿行剛處亢，以柔和為用，若不全任剛亢，務在和通，方欲為此和通，即虧減其悔，終獲吉矣。雨，喻陰陽和順也。</p><p>「九四，鼎折足，覆公餗，其形渥，兇」者，餗是八珍糝鼎之實也；渥，沾濡之貌。九四應在初，初已傾棄穢物，即九四有以受其珍美之物也。九四上近於五，即有承五之心，下又應初，又有施下之義，既承且施，力所不任，即致折足而傾棄其餗，故曰「鼎折足，覆公餗」。鼎足既折，覆於地，即被沙滷沾濡，喻之於人智小謀大，力小任重，受其至辱，災及其身，故曰「其形渥，兇」。</p><p>「六五：鼎黃耳金鉉，利貞。」者，黃中，謂五也；金剛，謂二也；鉉者，扛鼎之物也。六五以柔居中，故曰「黃耳」。應在九二，以柔納剛，納金鉉而以舉之，故曰「金鉉」也。所納剛正，不為虛妄，故曰「利貞」。</p><p>「上九：鼎玉鉉，大吉，無不利」者，堅剛之物而懷潤澤之性，喻道大成而有斯美，體剛履柔，是用玉鉉而以自舉，故曰「鼎玉鉉」也。應不在下，不私其用，故獲大吉而無不利，故曰「大吉，無不利」也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
